<?php
require 'config.php';
if(empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$uid=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("SELECT COUNT(*) total, SUM(status='Completed') done, SUM(status='Pending' AND due_date<CURDATE()) overdue FROM tasks WHERE user_id=?"); $stmt->bind_param('i',$uid); $stmt->execute(); $stats=$stmt->get_result()->fetch_assoc();
$stmt=$conn->prepare("SELECT t.*,s.name subject_name FROM tasks t LEFT JOIN subjects s ON s.id=t.subject_id WHERE t.user_id=? ORDER BY (t.status='Completed'),t.due_date,t.start_time LIMIT 100"); $stmt->bind_param('i',$uid); $stmt->execute(); $tasks=$stmt->get_result();
$stmt=$conn->prepare('SELECT id,name FROM subjects WHERE user_id=? ORDER BY name'); $stmt->bind_param('i',$uid); $stmt->execute(); $subjects=$stmt->get_result();
$done=(int)($stats['done']??0); $total=(int)($stats['total']??0); $pct=$total?round($done/$total*100):0;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | StudyNest</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body class="app-page"><nav class="navbar bg-white border-bottom"><div class="container"><a class="navbar-brand fw-bold" href="dashboard.php">✦ StudyNest</a><div class="d-flex align-items-center gap-3"><span class="small text-secondary d-none d-sm-inline">Hi, <?=htmlspecialchars($_SESSION['user_name'])?></span><a href="logout.php" class="btn btn-sm btn-outline-secondary">Log out</a></div></div></nav><main class="container py-4 py-lg-5"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><span class="eyebrow">STUDENT WORKSPACE</span><h1 class="h2 fw-bold mt-2 mb-1">Your study overview</h1><p class="text-secondary mb-0">Small steps add up. Keep your next task clear.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#taskModal">＋ Add task</button></div>
<div class="row g-3 mb-4"><div class="col-6 col-lg-3"><div class="stat-card"><small>Total tasks</small><div class="stat-number"><?=$total?></div><span class="text-secondary small">In your planner</span></div></div><div class="col-6 col-lg-3"><div class="stat-card"><small>Completed</small><div class="stat-number"><?=$done?></div><span class="text-success small">Nice work</span></div></div><div class="col-6 col-lg-3"><div class="stat-card"><small>Overdue</small><div class="stat-number"><?= (int)($stats['overdue']??0)?></div><span class="text-secondary small">Pending past due</span></div></div><div class="col-6 col-lg-3"><div class="stat-card"><small>Completion</small><div class="stat-number"><?=$pct?>%</div><div class="progress mt-2"><div class="progress-bar" style="width:<?=$pct?>%"></div></div></div></div></div>
<div class="row g-4"><div class="col-lg-8"><section class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 fw-bold mb-1">Your tasks</h2><p class="small text-secondary mb-0">Sort by due date and keep moving.</p></div><span class="soft-pill"><?=date('D, d M')?></span></div><?php if($tasks->num_rows===0):?><div class="empty-state"><div class="display-6">✎</div><b>No tasks yet</b><p class="text-secondary mb-3">Add a study session, assignment, or exam reminder.</p><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#taskModal">Add your first task</button></div><?php else: while($t=$tasks->fetch_assoc()):?><div class="task-row"><div class="task-mark <?=$t['status']==='Completed'?'is-done':''?>"><?= $t['status']==='Completed'?'✓':'•'?></div><div class="flex-grow-1"><div class="d-flex flex-wrap align-items-center gap-2"><b class="<?=$t['status']==='Completed'?'text-decoration-line-through text-secondary':''?>"><?=htmlspecialchars($t['title'])?></b><span class="badge rounded-pill bg-light text-secondary"><?=htmlspecialchars($t['task_type'])?></span></div><div class="small text-secondary mt-1"><?=htmlspecialchars($t['subject_name']??'No subject')?> · <?=date('D, d M Y',strtotime($t['due_date']))?><?= $t['start_time']?' · '.date('g:i A',strtotime($t['start_time'])):''?> · <?=htmlspecialchars($t['priority'])?> priority</div></div><div class="d-flex gap-2"><form method="post" action="task_action.php"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-sm <?=$t['status']==='Completed'?'btn-outline-secondary':'btn-outline-success'?>" title="Toggle completion"><?=$t['status']==='Completed'?'Undo':'Done'?></button></form><form method="post" action="task_action.php" onsubmit="return confirm('Delete this task?')"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger" aria-label="Delete task">×</button></form></div></div><?php endwhile; endif;?></section></div><div class="col-lg-4"><section class="panel mb-4"><h2 class="h5 fw-bold">Subjects</h2><form method="post" action="subject_action.php" class="d-flex gap-2 mt-3"><input class="form-control" name="subject_name" maxlength="100" placeholder="e.g. Java Programming" required><button class="btn btn-outline-primary">Add</button></form><div class="mt-3"><?php if($subjects->num_rows===0):?><p class="small text-secondary mb-0">Add subjects to group your tasks.</p><?php else:while($s=$subjects->fetch_assoc()):?><div class="subject-chip"><span class="dot blue"></span><?=htmlspecialchars($s['name'])?><form method="post" action="subject_action.php" class="ms-auto" onsubmit="return confirm('Delete this subject? Tasks will remain without a subject.')"><input type="hidden" name="subject_id" value="<?=$s['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm text-secondary p-0" aria-label="Delete subject">×</button></form></div><?php endwhile;endif;?></div></section><section class="panel tip-panel"><div class="fs-3">☀</div><h3 class="h6 fw-bold mt-2">A gentle reminder</h3><p class="small text-secondary mb-0">Choose one important task and give it your full attention for 25 minutes.</p></section></div></div></main>
<div class="modal fade" id="taskModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="task_action.php"><div class="modal-header"><h2 class="modal-title fs-5 fw-bold">Add a task</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Task title</label><input class="form-control mb-3" name="title" maxlength="180" required placeholder="Revise Java inheritance"><label class="form-label">Subject</label><select class="form-select mb-3" name="subject_id"><option value="">No subject</option><?php $subjects->data_seek(0);while($s=$subjects->fetch_assoc()):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endwhile;?></select><div class="row"><div class="col-6"><label class="form-label">Type</label><select class="form-select mb-3" name="task_type"><option>Study</option><option>Assignment</option><option>Exam</option><option>Revision</option></select></div><div class="col-6"><label class="form-label">Priority</label><select class="form-select mb-3" name="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></div></div><label class="form-label">Due date</label><input class="form-control mb-3" type="date" name="due_date" min="<?=date('Y-m-d')?>" required><label class="form-label">Start time (optional)</label><input class="form-control" type="time" name="start_time"></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save task</button></div></form></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
